 public static class ApplicationShortcutTests {
  static int checks;static readonly List<string> results=new List<string>();
  static void Check(bool test,string name){if(!test)throw new Exception(name);checks++;results.Add("PASS "+name);}
  static AppShortcutSource Fixture(string root,string name,string kind,string app,string title,string text){string path=Path.Combine(root,name);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));return new AppShortcutSource(path,kind,app,title);}
  static List<SystemShortcut> Read(AppShortcutSource source){byte[] before=File.ReadAllBytes(source.Path);var rows=ApplicationShortcutReaders.Read(source);Check(before.SequenceEqual(File.ReadAllBytes(source.Path)),"Read preserves bytes: "+source.Kind);Check(rows.All(r=>!r.Editable&&r.Snapshot==null),"New provider stays read-only with no retained settings snapshot: "+source.Kind);return rows;}
  static void Unit(string root){
   var npp=Fixture(root,"shortcuts.xml","Notepad++","notepad++.exe","Notepad++","<NotepadPlus><InternalCommands><Shortcut id='41006' Ctrl='yes' Alt='no' Shift='yes' Key='83'/><Shortcut id='1' Key='0'/></InternalCommands><Macros><Macro name='Build &amp; test' Ctrl='no' Alt='yes' Key='112'/></Macros></NotepadPlus>");var rows=Read(npp);Check(rows.Count==3&&rows[0].KeyText=="ctrl+shift+s"&&rows[1].Enabled==false&&rows[2].Name=="Build & test","Notepad++ overrides, disabled keys and macro names");
   var sublime=Fixture(root,"Default.sublime-keymap","Sublime Text","sublime_text.exe","Sublime Text","// local overrides\n[{\"keys\":[\"ctrl+k\",\"ctrl+c\"],\"command\":\"comment\",\"context\":[{\"key\":\"selection_empty\"}]},]");rows=Read(sublime);Check(rows.Single().KeyText=="ctrl+k ctrl+c"&&rows[0].When.Length>0,"Sublime JSONC chords preserve application context");
   var jet=Fixture(root,"keymaps/Custom.xml","JetBrains","idea64.exe","IntelliJ IDEA","<keymap name='Custom' parent='Default'><action id='Run'><keyboard-shortcut first-keystroke='ctrl alt R'/><keyboard-shortcut first-keystroke='ctrl K' second-keystroke='ctrl C'/></action></keymap>");rows=Read(jet);Check(rows.Count==2&&rows[0].KeyText=="ctrl+alt+r"&&rows[1].KeyText=="ctrl+k ctrl+c"&&rows.All(r=>r.When.Contains("inherited")),"JetBrains custom map does not invent inherited defaults");
   var vlc=Fixture(root,"vlcrc","VLC","vlc.exe","VLC","#key-play-pause=Space\nkey-play-pause=Ctrl+p\tSpace\nglobal-key-stop=Ctrl+Alt+s\nkey-next=\n");rows=Read(vlc);Check(rows.Count==4&&rows.Count(r=>r.Enabled)==3&&rows[2].App==""&&rows[0].App=="vlc.exe","VLC ignores comments, reads alternatives and preserves global scope");
   var powers=Fixture(root,"Keyboard Manager/default.json","PowerToys","PowerToys.exe","PowerToys","{\"remapKeys\":{\"inProcess\":[{\"originalKeys\":\"65\",\"newRemapKeys\":\"66\"}]},\"remapShortcuts\":{\"appSpecific\":[{\"originalKeys\":\"162;164;83\",\"newRemapKeys\":\"162;86\",\"targetApp\":\"brave\"}]}}");rows=Read(powers);Check(rows.Count==2&&rows[1].KeyText=="ctrl+alt+s"&&rows[1].App=="brave.exe"&&rows[0].App=="","PowerToys virtual keys and app-specific/global remaps");Check(ApplicationIndex.Matches(new DiscoveredApplication{Name="PowerToys",Executable="PowerToys.exe"},rows[1])&&ApplicationIndex.Matches(new DiscoveredApplication{Name="Brave",Executable="brave.exe"},rows[1]),"PowerToys remap appears under its owner and target application");
   var obs=Fixture(root,"obs-studio/basic/profiles/Test/basic.ini","OBS Studio","obs64.exe","OBS Studio","[Stream]\nKey=DO_NOT_COLLECT_SECRET\n[Hotkeys]\nOBSBasic.StartRecording={\"bindings\":[{\"key\":\"OBS_KEY_F9\",\"control\":true}]}\n");rows=Read(obs);Check(rows.Single().KeyText=="ctrl+f9"&&rows[0].App==""&&!LocalLlm.Json().Serialize(rows).Contains("DO_NOT_COLLECT_SECRET"),"OBS reads only hotkeys, retaining no stream configuration");
   var scene=Fixture(root,"obs-studio/basic/scenes/Test.json","OBS Studio","obs64.exe","OBS Studio","{\"hotkeys\":{\"OBSBasic.Pause\":[{\"key\":\"OBS_KEY_F8\"}]},\"sources\":[{\"hotkeys\":{\"libobs.mute\":[{\"key\":\"OBS_KEY_M\",\"alt\":true}]}}]}");rows=Read(scene);Check(rows.Count==2&&rows[1].KeyText=="alt+m","OBS scene/source hotkeys are included");
   var browser=Fixture(root,"Brave/Default/Preferences","Chromium extensions","brave.exe","Brave","{\"password\":\"DO_NOT_COLLECT_SECRET\",\"extensions\":{\"commands\":{\"windows:Ctrl+Shift+Y\":{\"extension\":\"test\",\"command_name\":\"toggle\",\"global\":true},\"mac:Command+Y\":{\"command_name\":\"mac-only\"}}}}");rows=Read(browser);Check(rows.Count==1&&rows[0].App==""&&rows[0].KeyText=="ctrl+shift+y"&&!LocalLlm.Json().Serialize(rows).Contains("DO_NOT_COLLECT_SECRET"),"Chromium reads Windows extension commands only, with no unrelated preferences");
   var brave=Fixture(root,"Brave/Current/Preferences","Brave shortcuts","brave.exe","Brave","{\"brave\":{\"accelerators\":{\"33000\":[\"Alt+ArrowLeft\"],\"34014\":[\"Control+Shift+KeyT\"],\"34015\":[],\"99999\":[\"Control+Digit1\"],\"39001\":[\"Control+Equal\"]},\"default_accelerators\":{\"34014\":[\"Control+KeyT\"]}},\"extensions\":{\"commands\":{\"windows:Ctrl+Y\":{\"command_name\":\"extension\"}}}}");rows=Read(brave);Check(rows.Count==6&&rows.Single(r=>r.Name=="Back").KeyText=="alt+left","Brave native shortcuts and extension commands are read together");Check(rows.Single(r=>r.Name=="New tab").KeyText=="ctrl+shift+t"&&rows.Single(r=>r.Name=="New tab").When.Contains("Customized"),"Brave customized keys override stored defaults without duplicate fallback");Check(!rows.Single(r=>r.Name=="Close tab").Enabled&&rows.Single(r=>r.Name=="Close tab").KeyText=="","Brave explicitly removed shortcuts stay disabled");Check(rows.Single(r=>r.Name=="Brave command 99999").KeyText=="ctrl+1"&&rows.Single(r=>r.Name=="Address bar").KeyText=="ctrl+oem_plus","Unknown Brave command IDs stay visible and DOM punctuation keys normalize");
   var minecraft=Fixture(root,"options.txt","Minecraft","javaw.exe","Minecraft","key_key.attack:key.mouse.left\nkey_key.forward:key.keyboard.w\nkey_key.custom:key.keyboard.unknown\nvolume:0.5\n");rows=Read(minecraft);Check(rows.Count==3&&rows[0].KeyText=="lbutton"&&rows[1].KeyText=="w"&&!rows[2].Enabled,"Minecraft keyboard, mouse and unassigned bindings");Check(ApplicationIndex.Matches(new DiscoveredApplication{Name="Minecraft",Executable="javaw.exe"},rows[0]),"Minecraft bindings use a discoverable logical app identity");
   var league=Fixture(root,"League of Legends/Config/input.ini","League of Legends","League of Legends.exe","League of Legends","[GameEvents]\nevtCastSpell1=[q],[Shift+q]\nevtUnused=[]\nCameraSpeed=50\n");rows=Read(league);Check(rows.Count==3&&rows[0].KeyText=="q"&&rows[1].KeyText=="shift+q"&&!rows[2].Enabled,"League alternatives and empty assignments");
   File.WriteAllText(league.Path,"[GameEvents]\nevtMouse=[Ctrl Button 5]\nevtSpace=[ ]\nevtUnbound=[<Unbound>]\n");rows=ApplicationShortcutReaders.Read(league);Check(rows[0].KeyText=="ctrl+xbutton2"&&rows[1].KeyText=="space"&&!rows[2].Enabled,"League mouse buttons, space and explicit unbound keys are distinct");
   var cs=Fixture(root,"cs2_user_keys_0_slot0.vcfg","Counter-Strike 2","cs2.exe","Counter-Strike 2","\"config\"\n{\n\"bindings\"\n{\n\"MOUSE1\" \"+attack\"\n\"F5\" \"say test\"\n\"scancode26\" \"+forward\"\n}\n\"other\" \"ignored\"\n}");rows=Read(cs);Check(rows.Count==3&&rows[0].KeyText=="lbutton"&&rows[1].KeyText=="f5"&&rows[2].KeyText=="scancode26"&&!ShortcutKeys.Comparable(rows[2].KeyText),"CS2 mouse/function keys normalize while physical scancodes stay literal");
   bool failed=false;try{SystemShortcuts.WriteCode(rows[0],"f8","bad","");}catch(InvalidOperationException){failed=true;}Check(failed,"Read-only app formats cannot reach the JSONC writer");failed=false;try{SystemShortcuts.Restore(rows[0]);}catch(InvalidOperationException){failed=true;}Check(failed,"Read-only app formats cannot restore arbitrary backups");
   var evil=Fixture(root,"evil/shortcuts.xml","Notepad++","notepad++.exe","Notepad++","<!DOCTYPE x [<!ENTITY ext SYSTEM 'file:///missing-private-file'>]><NotepadPlus>&ext;</NotepadPlus>");failed=false;try{ApplicationShortcutReaders.Read(evil);}catch(System.Xml.XmlException){failed=true;}Check(failed,"XML external entities and DTDs are prohibited");
   string big=Path.Combine(root,"oversized.sublime-keymap");using(var file=File.Create(big))file.SetLength(ApplicationShortcutReaders.MaxBytes+1L);failed=false;try{ApplicationShortcutReaders.Read(new AppShortcutSource(big,"Sublime Text","sublime_text.exe","Sublime Text"));}catch(InvalidDataException){failed=true;}Check(failed,"Oversized files are rejected before parsing");
   var scan=SystemShortcuts.Scan(new[]{npp.Path,sublime.Path,evil.Path,big},false);Check(scan.Items.Count==4&&scan.AppSources.Count==4&&scan.Warnings.Count==2,"A damaged/oversized provider does not hide other application shortcuts");
   string unicode=Path.Combine(root,"Antigravity","User");Directory.CreateDirectory(unicode);string code=Path.Combine(unicode,"keybindings.json");File.WriteAllText(code,"[{\"key\":\"ctrl+alt+k\",\"command\":\"example.command\"}]",Encoding.Unicode);Check(SystemShortcuts.ReadCode(code).Single().App=="Antigravity.exe","Antigravity user settings resolve to its own executable");
   var app=new DiscoveredApplication{Name="Brave",Executable=@"C:\Apps\brave.exe"};var binding=new Binding{Name="Open website",Key=120,Kind="Browser website",BrowserPath=app.Executable,Target="https://example.com"};Check(ApplicationIndex.Matches(app,binding),"Global launch assignments remain attached to their destination app");Check(!ApplicationIndex.Matches(app,new Binding{Kind="Send key"})&&ApplicationIndex.Matches(app,new Binding{Kind="Send key"},true),"Global unrelated assignments require an explicit include option");
   var external=new SystemShortcut{Id="found",Provider="App: VLC",Name="Test",App="vlc.exe",KeyText="ctrl+alt+k",Command="test"};var conflicts=ShortcutConflicts.Find(new[]{new Binding{Name="Global",Key=75,Mods=3}},new[]{external});Check(conflicts.Count==1,"New application sources take part in existing conflict checks");
   var index=ApplicationIndex.Build(new[]{app,new DiscoveredApplication{Name="Unsupported app",Executable="unsupported.exe"}},new[]{binding},new SystemShortcut[0],new AppSourceResult[0]);Check(index.Count==2&&index.Single(i=>i.Application.Id==app.Id).Personal==1&&index.All(i=>i.Coverage=="No readable app settings source found"),"Unsupported apps stay visible with honest coverage, not a no-shortcuts claim");
   Check(ApplicationShortcutReferences.Items().All(r=>r.Reference&&!r.Editable)&&ApplicationShortcutReferences.Items().Any(r=>r.App=="Spotify.exe")&&ApplicationShortcutReferences.Items().Any(r=>r.App=="Discord.exe"),"Spotify and Discord documented defaults stay separate from scanned custom settings");
   var many=Enumerable.Range(0,5000).Select(i=>new SystemShortcut{Id="perf"+i,Provider="App: Synthetic",App="test"+(i%100)+".exe",Name="Action "+i,KeyText="ctrl+s",Command="test"}).ToArray();var watch=System.Diagnostics.Stopwatch.StartNew();var indexed=ApplicationIndex.Build(new DiscoveredApplication[0],new Binding[0],many,new AppSourceResult[0]);Check(indexed.Count==100&&indexed.Sum(i=>i.Detected)==5000,"Application index retains 5000 assignments without duplicate counts");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"application-index-performance.json"),LocalLlm.Json().Serialize(new{records=many.Length,applications=indexed.Count,milliseconds=watch.ElapsedMilliseconds}));
   Check(ShortcutConflicts.ForBinding(new Binding{Name="Unrelated",Key=117},many).Count==0,"Draft conflict checks skip pairs unrelated to the edited binding");var dense=Enumerable.Range(0,110).Select(i=>new SystemShortcut{Id="dense"+i,Provider="App: Synthetic",App="test.exe",Name="Action "+i,KeyText="ctrl+s"});var capped=ShortcutConflicts.Find(new Binding[0],dense);Check(capped.Count==5001&&capped.Last().Severity=="NOTICE","Dense sources have an explicit bounded-conflict notice instead of unbounded UI work");
   NativeFixture();
  }
  [DllImport("user32.dll")]static extern IntPtr CreateMenu();
  [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern bool AppendMenu(IntPtr menu,uint flags,UIntPtr id,string text);
  [DllImport("user32.dll")]static extern bool SetMenu(IntPtr window,IntPtr menu);
  [DllImport("user32.dll")]static extern bool DestroyMenu(IntPtr menu);
  static void NativeFixture(){using(var form=new System.Windows.Forms.Form()){IntPtr menu=CreateMenu();try{AppendMenu(menu,0,new UIntPtr(1),"&Copy\tCtrl+C");AppendMenu(menu,1,new UIntPtr(2),"Disabled\tCtrl+Shift+S");SetMenu(form.Handle,menu);var rows=NativeMenuShortcuts.ReadWindow(form.Handle);Check(rows.Count==2&&rows[0].Name=="Copy"&&rows[0].KeyText=="ctrl+c"&&rows[1].Enabled&&rows[1].When.Contains("unavailable"),"Real native menu labels are read without clicking or sending input");}finally{SetMenu(form.Handle,IntPtr.Zero);DestroyMenu(menu);}}}
  static void Screenshot(Window window,string name){window.UpdateLayout();Application.Current.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));var bitmap=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(window);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name)))png.Save(file);}
  static void UiCheck(string root){string executable=Path.Combine(root,"brave.exe");File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,executable);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Theme.Install(app);var state=new State{Language="tr",Paused=true,Gestures=new GestureOptions{Enabled=false}};state.Bindings.Add(new Binding{Name="Open example",Kind="Browser website",BrowserPath=executable,Target="https://example.com",Key=120});var window=new MainWindow(state,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"app-scan-ui-settings.json"));app.MainWindow=window;window.Show();var scan=new ShortcutScan();scan.Applications.Add(new DiscoveredApplication{Name="Brave",Executable=@"C:\Apps\brave.exe"});scan.Applications.Add(new DiscoveredApplication{Name="Unsupported app",Executable="unsupported.exe"});var source=Fixture(root,"Brave/UI/Preferences","Brave shortcuts","brave.exe","Brave","{\"brave\":{\"accelerators\":{\"33000\":[\"Alt+ArrowLeft\"],\"33002\":[\"Control+KeyR\"],\"34014\":[\"Control+Shift+KeyT\"],\"34015\":[],\"39001\":[\"Control+KeyL\"],\"40012\":[\"Control+KeyJ\"]},\"default_accelerators\":{\"34014\":[\"Control+KeyT\"]}},\"extensions\":{\"commands\":{}}}");scan.Items.AddRange(ApplicationShortcutReaders.Read(source));scan.AppSources.Add(new AppSourceResult{Source=source,Success=true,Count=scan.Items.Count});window.ApplicationScanForTest(scan);window.FindApplicationForTest("Brave");Check(window.ApplicationRowsForTest==6,"App search shows detected keys and Makro+ launch assignments together");Screenshot(window,"app-shortcuts-tr.png");window.FilterApplicationRowsForTest(1,"");Check(window.ApplicationRowsForTest==5,"From apps filter excludes personal entries");window.FilterApplicationRowsForTest(2,"");Check(window.ApplicationRowsForTest==1,"Makro+ source filter shows personal entries");window.FilterApplicationRowsForTest(0,"New tab");Check(window.ApplicationRowsForTest==1,"Action search filters actual detected commands");window.FilterApplicationRowsForTest(0,"",true);Check(window.ApplicationRowsForTest==7,"Explicit unassigned Brave commands remain inspectable");window.FilterApplicationRowsForTest(0,"");window.FindApplicationForTest("Unsupported");Check(window.ApplicationRowsForTest==0&&window.ApplicationCoverageForTest.Contains("bulunamadı"),"An unreadable app displays coverage instead of pretending it has no shortcuts");window.FindApplicationForTest("does-not-exist");Check(window.ApplicationRowsForTest==0,"No-match search clears stale rows");window.ChangeLanguage("en");window.ApplicationScanForTest(scan);window.FindApplicationForTest("Brave");Screenshot(window,"app-shortcuts-en.png");window.Close();app.Shutdown();}
  public static int Run(bool ui=false,bool live=false){string folder=Path.Combine(Path.GetTempPath(),"MakroPlus-AppScan-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,live?"application-scan-live.json":"application-scan-tests.txt");try{if(live){var state=Storage.Read(Storage.FilePath);var watch=System.Diagnostics.Stopwatch.StartNew();var scan=SystemShortcuts.Scan(state.ShortcutSources,true,state.ApplicationPaths);var index=ApplicationIndex.Build(scan.Applications,state.Bindings,scan.Items,scan.AppSources);File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",milliseconds=watch.ElapsedMilliseconds,files=scan.Files,detected=scan.Items.Count(i=>i.Enabled),settingsSources=scan.AppSources.Count,warnings=scan.Warnings.Count,applications=index.Select(i=>new{name=i.Application.Name,detected=i.Detected,personal=i.Personal,coverage=i.Coverage}),sources=scan.AppSources.Select(s=>new{app=s.Source.Name,format=s.Source.Kind,entries=s.Count,success=s.Success})}));return 0;}Unit(folder);if(ui)UiCheck(folder);File.WriteAllLines(report,new[]{"PASS: "+checks+" application scan checks"}.Concat(results));return 0;}catch(Exception error){File.WriteAllText(report,"FAIL after "+checks+" checks\n"+error);return 1;}finally{string cleanup=Path.GetFullPath(folder);string parent=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!cleanup.StartsWith(parent,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(cleanup).StartsWith("MakroPlus-AppScan-",StringComparison.Ordinal))throw new InvalidOperationException("Unexpected test cleanup directory.");if(Directory.Exists(cleanup))Directory.Delete(cleanup,true);}}
 }
